options.afterRender:
// Forging Health: header afterRender JS (shared suite prelude + this dashboard's KPIs)
(function () {
  var ROOT_ID = 'hx-forging';
  try {

  var s = (context && context.panelData && context.panelData.series) ? context.panelData.series : [];
  function lastv(v) { if (!v) return undefined; for (var i = v.length - 1; i >= 0; i--) { var x = v[i]; if (x !== null && x !== undefined && isFinite(x)) return Number(x) } return undefined }
  /* rows(ref): [{l: labels, v: last value}] for every series of that query */
  /* two namespaces can both run relay-0: a pod name seen in more than one namespace is keyed and shown as namespace/pod; podRaw keeps the bare name */
  var podNs = {};
  for (var sn = 0; sn < s.length; sn++) {
    var fn = (s[sn] && s[sn].fields) || [];
    for (var jn = 0; jn < fn.length; jn++) {
      var lbn = fn[jn].labels;
      if (lbn && lbn.pod && lbn.namespace) { var qn = podNs[lbn.pod] = podNs[lbn.pod] || {}; qn[lbn.namespace] = 1 }
    }
  }
  function podId(lb) {
    var o = {}; for (var k in lb) o[k] = lb[k];
    if (lb.pod) { o.podRaw = lb.pod; var q = podNs[lb.pod]; if (q && lb.namespace && Object.keys(q).length > 1) o.pod = lb.namespace + '/' + lb.pod }
    return o;
  }
  function rows(ref) {
    var out = [];
    for (var si = 0; si < s.length; si++) {
      if (!s[si] || s[si].refId !== ref) continue;
      var f = s[si].fields || [];
      for (var j = 0; j < f.length; j++) {
        if (f[j].type !== 'number') continue;
        var v = lastv(f[j].values && f[j].values.toArray ? f[j].values.toArray() : f[j].values);
        if (v !== undefined) out.push({ l: podId(f[j].labels || {}), v: v });
      }
    }
    return out;
  }
  function one(ref) { var r = rows(ref); return r.length ? r[0].v : undefined }
  function sum(ref) { var r = rows(ref), t = 0; for (var i = 0; i < r.length; i++) t += r[i].v; return r.length ? t : undefined }
  function minRow(r) { var m = null; for (var i = 0; i < r.length; i++) if (!m || r[i].v < m.v) m = r[i]; return m }
  function maxRow(r) { var m = null; for (var i = 0; i < r.length; i++) if (!m || r[i].v > m.v) m = r[i]; return m }
  function byLabel(ref, label) { var r = rows(ref), o = {}; for (var i = 0; i < r.length; i++) { var k = r[i].l[label]; if (k !== undefined) o[k] = r[i].v } return o }
  function has(x) { return x !== undefined && x !== null && isFinite(x) }
  function n0(x) { return has(x) ? String(Math.round(x)) : '–' }
  function ms(sec) { if (!has(sec)) return '–'; var m = sec * 1000; return m >= 10000 ? (m / 1000).toFixed(1) + ' s' : (m >= 100 ? Math.round(m) : (m >= 10 ? m.toFixed(0) : m.toFixed(1))) + ' ms' }
  function plural(n, one_, many) { return n + ' ' + (n === 1 ? one_ : many) }
  function names(a, max) { max = max || 3; return a.length <= max ? a.join(', ') : a.slice(0, max).join(', ') + ' +' + (a.length - max) }
  function esc(t) { return String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;') }
  var RANK = { na: 0, ok: 1, warn: 2, bad: 3 };
  function worst(a, b) { return RANK[b] > RANK[a] ? b : a }
  /* lower is better: ok under w, warn under b, else bad */
  function low(x, w, b) { return !has(x) ? 'na' : (x < w ? 'ok' : (x < b ? 'warn' : 'bad')) }
  /* higher is better: ok at or above g, warn at or above a, else bad */
  function high(x, g, a) { return !has(x) ? 'na' : (x >= g ? 'ok' : (x >= a ? 'warn' : 'bad')) }
  function el(id) { return document.getElementById(id) }
  var root = el(ROOT_ID);
  /* light theme: ask Grafana, else infer it from the inherited text colour (dark text = light theme) */
  try {
    var th = context.grafana && context.grafana.theme, light = null;
    if (th && typeof th.isDark === 'boolean') light = !th.isDark;
    if (light === null && root && typeof getComputedStyle === 'function') {
      var m = /(\d+)[, ]+(\d+)[, ]+(\d+)/.exec(getComputedStyle(root).color || '');
      if (m) light = (0.299 * m[1] + 0.587 * m[2] + 0.114 * m[3]) < 128;
    }
    if (root && light && String(root.className).indexOf('hx-light') < 0) root.className += ' hx-light';
  } catch (e) { }
  /* fit(): a dynamic-text panel scrolls inside itself when its content is taller than the panel, and that
     captures the page scroll. Find the scrolling ancestor and, while the content overflows it, step through the
     compact levels (hx-fit1 drops the detail line, hx-fit2 also thins the rows and drops the legend). */
  function fit() {
    try {
      if (!root || !root.parentElement || typeof getComputedStyle !== 'function') return;
      root.className = String(root.className).replace(/ hx-fit\d/g, '');
      var box = root.parentElement, found = false;
      /* only a scroller inside this panel counts: stop at the panel chrome (<section>) or the grid item */
      while (box && box !== document.body) {
        var cls = typeof box.className === 'string' ? box.className : '';
        if (box.tagName === 'SECTION' || cls.indexOf('react-grid-item') >= 0) break;
        var oy = getComputedStyle(box).overflowY;
        if ((oy === 'auto' || oy === 'scroll') && box.clientHeight > 0) { found = true; break }
        box = box.parentElement;
      }
      if (!found) return;
      for (var lvl = 1; lvl <= 2 && box.scrollHeight > box.clientHeight + 1; lvl++) root.className += ' hx-fit' + lvl;
    } catch (e) { }
  }
  function dur(sec) { if (!has(sec)) return '–'; var a = Math.abs(sec); if (a < 90) return Math.round(a) + ' s'; if (a < 5400) return Math.round(a / 60) + ' min'; if (a < 172800) return (a / 3600).toFixed(a < 36000 ? 1 : 0) + ' h'; return (a / 86400).toFixed(a < 864000 ? 1 : 0) + ' d' }
  var overall = 'na';
  /* kpi(key, value, unit, status, note): fill one tile; value '–' when undefined */
  function kpi(key, value, unit, status, note) {
    var t = el(ROOT_ID + '-k-' + key); if (!t) return;
    var miss = value === undefined || value === null || value === '–';
    var st = miss ? 'na' : (status || 'na');
    t.setAttribute('data-s', st);
    var c = t.children;
    if (c[1]) c[1].innerHTML = miss ? '–' : esc(value) + (unit ? '<small>' + esc(unit) + '</small>' : '');
    if (c[2]) c[2].textContent = miss ? (note || 'no data') : (note || '');
    if (c[2]) c[2].title = miss ? '' : (note || '');
    overall = worst(overall, st);
  }
  /* pills(list): one status pill per node, [{n: name, w: word, st: ok|warn|bad|na, t: tooltip, x: detail}] */
  function pills(list) {
    var c = el(ROOT_ID + '-pills'); if (!c) return;
    var order = { bad: 0, warn: 1, na: 2, ok: 3 };
    list.sort(function (a, b) { return (order[a.st] - order[b.st]) || String(a.n).localeCompare(String(b.n)) });
    c.innerHTML = list.map(function (p) {
      return '<span class="hx-pill" data-s="' + p.st + '" title="' + esc(p.t || '') + '"><i></i>' + esc(p.n) +
        ' <b>' + esc(p.w) + '</b>' + (p.x ? ' <small>' + esc(p.x) + '</small>' : '') + '</span>';
    }).join('');
  }
  function nodeName(l) { return l.pod || '?' }
  var BADGE = { ok: 'Healthy', warn: 'Attention', bad: 'Action needed', na: 'No data' };
  function verdict(html, status) {
    var st = status || overall;
    if (root) root.setAttribute('data-s', st);
    var b = el(ROOT_ID + '-badge'); if (b) b.lastChild.textContent = BADGE[st];
    var v = el(ROOT_ID + '-verdict'); if (v) v.innerHTML = html;
    fit();
  }

  var rdy = rows('RDY'), live = {}, total = rdy.length, notReady = [];
  for (var i = 0; i < rdy.length; i++) { var a = rdy[i].l.pod || '?'; live[a] = 1; if (rdy[i].v < 1) notReady.push(a) }
  /* range counters also return producers that no longer exist; keep the live ones */
  function cur(ref) { return rows(ref).filter(function (r) { return live[r.l.pod] }) }
  function tot(r) { var t = 0; for (var i = 0; i < r.length; i++) t += Math.round(r[i].v); return t }
  function who(r) { return r.filter(function (x) { return Math.round(x.v) > 0 }).map(function (x) { return x.l.pod }) }
  var issues = [], sev = 'ok';
  function issue(st, text) { issues.push({ st: st, text: text }); sev = worst(sev, st) }
  if (!total) kpi('rdy'); else kpi('rdy', (total - notReady.length) + '/' + total, '', notReady.length ? 'bad' : 'ok', notReady.length ? 'not ready: ' + names(notReady) : 'credentials valid');
  if (notReady.length) issue('bad', '<b>' + esc(names(notReady)) + '</b> cannot sign (credentials not valid)');
  var pGap = byLabel('GAP', 'pod'), pKes = byLabel('KES', 'pod'), pOpc = {}, pStk = {};
  cur('OPC').forEach(function (r) { pOpc[r.l.pod] = 1 });
  cur('STK').forEach(function (r) { pStk[r.l.pod] = 1 });
  pills(rdy.map(function (r) {
    var a = nodeName(r.l), g = pGap[a], k = pKes[a];
    var kx = has(k) ? n0(k) + ' KES' : '';
    if (r.v < 1) return { n: a, w: 'Cannot sign', st: 'bad', x: kx, t: 'credentials not valid at the current slot' };
    if (pOpc[a]) return { n: a, w: 'Opcert behind', st: 'bad', x: kx, t: 'loaded opcert counter is below the on-chain counter; blocks are rejected' };
    if (pStk[a]) return { n: a, w: 'Stalled', st: 'bad', x: kx, t: 'ledger pipeline stuck or halted' };
    if (has(g) && g > 300) return { n: a, w: 'Off tip', st: 'warn', x: n0(g) + ' slots', t: n0(g) + ' slots behind; forging is skipped until it is back at tip' };
    if (has(k) && k <= 8) return { n: a, w: 'KES due', st: k > 4 ? 'warn' : 'bad', x: kx, t: n0(k) + ' KES periods left' };
    return { n: a, w: 'Ready', st: 'ok', x: kx, t: 'credentials valid, at tip' };
  }));
  var stuck = cur('STK').map(function (r) { return r.l.pod });
  if (stuck.length) issue('bad', 'ledger pipeline stuck on <b>' + esc(names(stuck)) + '</b>');
  var behind = cur('OPC').map(function (r) { return r.l.pod });
  if (behind.length) issue('bad', 'opcert counter on <b>' + esc(names(behind)) + '</b> is behind the chain, so its blocks are rejected');
  var wonR = cur('WON'), adpR = cur('ADP'), blkKnown = wonR.length > 0 && adpR.length > 0, yldN = tot(cur('YLD')), won = blkKnown ? tot(wonR) : 0, adp = tot(adpR), lost = Math.max(0, won - yldN - adp);
  if (!blkKnown) kpi('blk', undefined, '', 'na', 'leader-slot or adopted-block counter not reported'); else if (!won) kpi('blk', '0', 'slots', 'na', 'no leader slot in this range');
  else kpi('blk', adp + '/' + (won - yldN), '', lost === 0 ? 'ok' : (lost / Math.max(1, won - yldN) > 0.1 ? 'bad' : 'warn'), lost ? lost + ' leader ' + (lost === 1 ? 'slot' : 'slots') + ' lost' : (yldN ? 'every leader slot adopted; ' + yldN + ' yielded to an own pool' : 'every leader slot adopted'));
  var missed = who(cur('MIS'));
  if (lost) issue(lost / Math.max(1, won - yldN) > 0.1 ? 'bad' : 'warn', '<b>' + lost + ' of ' + (won - yldN) + '</b> leader slots did not become an adopted block' + (missed.length ? ' (missed on ' + esc(names(missed)) + ')' : ''));
  var slow = maxRow(cur('FT')), pct = slow ? Math.round(slow.v * 100) : 0;
  kpi('frg', slow ? n0(slow.v * 1000) : undefined, 'ms', slow ? low(slow.v, 0.25, 1) : 'na', slow ? (slow.l.pod || '') + ' · ' + pct + '% of slot' : 'no block in this range');
  if (slow && slow.v >= 0.25) issue(low(slow.v, 0.25, 1), 'a forge on <b>' + esc(slow.l.pod) + '</b> takes ' + ms(slow.v) + ', ' + pct + '% of the 1 s slot');
  var okR = cur('SOK'), sok = tot(okR), sfR = cur('SF'), sf = tot(sfR);
  if (!okR.length) kpi('sgn', undefined, '', 'na', 'no agent producer selected');
  else kpi('sgn', String(sok), 'ok', sf ? 'warn' : 'ok', sf ? sf + ' failed on ' + names(who(sfR)) : 'no failed sign');
  if (sf) issue('warn', plural(sf, 'agent sign', 'agent signs') + ' failed on <b>' + esc(names(who(sfR))) + '</b>');
  var dfR = cur('DF'), df = tot(dfR);
  if (df) issue('warn', plural(df, 'failed dial', 'failed dials') + ' to the KES agent from <b>' + esc(names(who(dfR))) + '</b>');
  var skp = who(cur('SKP'));
  if (skp.length) issue('warn', '<b>' + esc(names(skp)) + '</b> skipped forging on a stale or syncing tip');
  /* leader-schedule series (a newer Dingo): no rows before the upgrade, so nothing below changes until then */
  var unc = cur('UNC'), nUnc = tot(unc);
  if (nUnc) issue('warn', '<b>' + plural(nUnc, 'scheduled leader slot', 'scheduled leader slots') + '</b> passed without a leader check on <b>' + esc(names(who(unc))) + '</b> (syncing or stale tip)');
  var knr = cur('KNR'), nKnr = tot(knr);
  if (nKnr) issue('warn', 'the remote KES signer was not ready ahead of ' + plural(nKnr, 'leader slot', 'leader slots') + ' on <b>' + esc(names(who(knr))) + '</b>');
  var nxt = minRow(cur('NXT')), nxn = cur('NXN'), nt = el(ROOT_ID + '-k-nxt');
  if (nt && nt.style) nt.style.display = nxt || nxn.length ? '' : 'none';
  if (nxt) kpi('nxt', nxt.v <= 0 ? 'now' : dur(nxt.v), '', 'ok', (nxt.l.pod || '') + ' · soonest');
  else if (nxn.length && nt) { kpi('nxt', 'none', '', 'ok', 'none in the cached schedules'); nt.setAttribute('data-s', 'na') }
  var kes = minRow(cur('KES'));
  kpi('kes', kes ? n0(kes.v) : undefined, 'periods', kes ? high(kes.v, 8, 4) : 'na', kes ? (kes.l.pod || '') + ' · ' + n0(kes.v * 1.5) + ' days' : '');
  if (kes && kes.v < 8) issue(high(kes.v, 8, 4), 'KES on <b>' + esc(kes.l.pod) + '</b> has ' + plural(Math.round(kes.v), 'period', 'periods') + ' left');
  var lag = maxRow(cur('GAP'));
  kpi('lag', lag ? n0(lag.v) : undefined, 'slots', lag ? low(lag.v, 300, 600) : 'na', lag ? (lag.l.pod || '') + ' · furthest' : '');
  if (lag && lag.v >= 300) issue(low(lag.v, 300, 600), '<b>' + esc(lag.l.pod) + '</b> is ' + n0(lag.v) + ' slots behind the wall clock');
  if (!total) { verdict('No producer matches the network and pod filters.', 'na') }
  else if (!issues.length) {
    verdict((total === 1 ? 'The producer is ready' : 'All ' + total + ' producers are ready') +
      (!blkKnown ? '; the leader-slot counters are not reported' : (won ? '; ' + adp + ' of ' + (won - yldN) + ' leader slots became adopted blocks' : '; no leader slot in this range')) +
      (slow ? '; slowest forge ' + ms(slow.v) + ' on ' + esc(slow.l.pod) + ' (' + pct + '% of the 1 s slot)' : '') + '.', blkKnown ? 'ok' : 'na');
  } else {
    issues.sort(function (x, y) { return RANK[y.st] - RANK[x.st] });
    var txt = issues.slice(0, 3).map(function (x) { return x.text }).join('; ');
    if (issues.length > 3) txt += '; and ' + (issues.length - 3) + ' more';
    if (txt.charAt(0) !== '<') txt = txt.charAt(0).toUpperCase() + txt.slice(1);
    verdict(txt + '. ' + (total - notReady.length) + ' of ' + total + ' producers ready' + (blkKnown && won ? ', ' + adp + ' of ' + (won - yldN) + ' leader slots adopted.' : '.'), sev);
  }

  } catch (e) {
    var v = document.getElementById(ROOT_ID + '-verdict');
    if (v) v.textContent = 'Header script error: ' + (e && e.message ? e.message : e);
  }
})();

options.styles:
